Method.Source:
/// <summary>
/// SalesLine_OnWritten
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(SalesTable, SalesLine), FormDataSourceEventType::Written)]
public static void SalesLine_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun         fr              = sender.formRun();
    SalesLine       salesLine       = sender.cursor();
    METSalesLine    metSalesLine    = fr.dataHelper().FindDataSource(formDataSourceStr(SalesTable, METSalesLine)).cursor();
    metSalesLine.SalesLine = salesLine.RecId;
    FormDataUtil::getFormDataSource(metSalesLine).write();
}
